head.script:
scwin.onpageload = function() {
    var data1 = [{
            "value": "13"
        },
        {
            "value": "51"
        },
        {
            "value": "28"
        },
        {
            "value": "36"
        },
        {
            "value": "45"
        },
        {
            "value": "15"
        },
        {
            "value": "64"
        },
        {
            "value": "47"
        },
        {
            "value": "49"
        },
        {
            "value": "91"
        }
    ];
    dataList2.setJSON(data1, false);
    fwGaugeChart3.draw();
    fwGaugeChart3.setValue("13");
    var jsonData = {
        "data": [{
                "value": "490000",
                "label": "China"
            },
            {
                "value": "340000",
                "label": "USA"
            },
            {
                "value": "160000",
                "label": "Brazil"
            },
            {
                "value": "220000",
                "label": "Spain"
            },
            {
                "value": "123000",
                "label": "India"
            }
        ]
    };
    //var chartObj =  dltChart.getFusionChartData( "Line" , "name" , "[['salery']]");
    var options = {
        //theme: themeStr,
        caption: "전세계 판매량 요약",
        subCaption: "2006년 동안",
        yAxisName: " 금액 ",
        xAxisName: " 나라 ",
        numberPrefix: "$"
    };
    chartBar1.setChartAttribute(options);
    // trendLine 옵션입니다.
    var lineOptions1 = {
        startValue: "440000",
        color: "1D8BD1",
        displayValue: "최대임계치"
    };
    chartBar1.addTrendLine(lineOptions1);
    var lineOptions2 = {
        startValue: "220000",
        color: "FF0000",
        displayValue: "최소임계치"
    };
    chartBar1.addTrendLine(lineOptions2);
    // 스타일옵션입니다.
    var styleOptions = {
        color: "2a5900",
        size: "20",
        bold: "1",
        underline: "0"
    };
    chartBar1.applyStyle("font", "captionFont", styleOptions, ["Caption"]);
    // 실제 데이터를 셋팅합니다. 차트가 그려집니다.
    chartBar1.setJSONData(jsonData);
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('fw_gauge_mf_fwGaugeChart3') != null", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
